    if total < quantity:
        raise InsufficientStock(sku, quantity, total)

    single = next((w for w in priority if remaining[w].get(sku, 0) >= quantity), None)
    if single is not None:
        remaining[single][sku] -= quantity
        plan.setdefault(single, []).append((sku, quantity))
        continue

    needed = quantity
    for w in priority:
        if needed <= 0:
            break
        take = min(remaining[w].get(sku, 0), needed)
        if take:
            remaining[w][sku] -= take
            plan.setdefault(w, []).append((sku, take))
            needed -= take

return plan

